 (()=>{const q=(s,c=document)=>c.querySelector(s),qa=(s,c=document)=>[...c.querySelectorAll(s)];const track=(name,params={})=>{if(typeof window.gtag==='function')window.gtag('event',name,params)};const menu=q('#menuToggle'),nav=q('#navLinks');if(menu&&nav){menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}})}qa('[data-track]').forEach(el=>el.addEventListener('click',()=>track(el.dataset.track,{link_text:(el.textContent||'').trim(),link_url:el.href||''})));const gallery=qa('[data-gallery]'),lb=q('#lightbox'),lbImg=q('#lightboxImage'),lbCap=q('#lightboxCaption');let idx=0,lastFocus=null;const open=i=>{idx=i;const b=gallery[idx];lbImg.src=b.dataset.full;lbImg.alt=b.dataset.alt;lbCap.textContent=b.dataset.alt;lastFocus=b;lb.classList.add('open');lb.setAttribute('aria-hidden','false');q('.lb-close',lb).focus();document.body.style.overflow='hidden';track('gallery_open',{image_name:b.dataset.full})};const close=()=>{lb.classList.remove('open');lb.setAttribute('aria-hidden','true');document.body.style.overflow='';if(lastFocus)lastFocus.focus()};gallery.forEach((b,i)=>b.addEventListener('click',()=>open(i)));if(lb){q('.lb-close',lb).addEventListener('click',close);q('.lb-prev',lb).addEventListener('click',()=>open((idx-1+gallery.length)%gallery.length));q('.lb-next',lb).addEventListener('click',()=>open((idx+1)%gallery.length));lb.addEventListener('click',e=>{if(e.target===lb)close()});document.addEventListener('keydown',e=>{if(!lb.classList.contains('open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')open((idx-1+gallery.length)%gallery.length);if(e.key==='ArrowRight')open((idx+1)%gallery.length)})}const map=q('#loadMap');if(map)map.addEventListener('click',()=>{const box=q('#mapBox');box.innerHTML='<iframe title="Google Map showing 41 Hardinge Road, Liverpool L19 4UN" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=41+Hardinge+Road+Liverpool+L19+4UN&output=embed"></iframe>';track('map_load')});const share=q('#shareButton');if(share)share.addEventListener('click',async()=>{const data={title:document.title,text:'Three-bedroom semi-detached house for sale in Liverpool L19 — offers over £265,000.',url:location.href};try{if(navigator.share){await navigator.share(data)}else{await navigator.clipboard.writeText(location.href);share.textContent='Link copied'}}catch(e){}track('share_click')});const video=q('#roadVideo');if(video)video.addEventListener('play',()=>track('video_play',{video_title:'Hardinge Road road view'}),{once:true});})(); 